edits.new:
const { Reader } = require('widget');
const reader = new Reader();
const memo = new Map();

async function describe(key) {
  if (memo.has(key)) {
    return memo.get(key);
  }
  console.log('reading', key);
  const value = await reader.read(key);
  const result = value.toUpperCase();
  memo.set(key, result);
  return result;
}

function clearMemo() {
  memo.clear();
}

module.exports = { describe, clearMemo };

