function pack(text) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  console.log('packing', text.length);
  return compress(text, { compressionLevel: 3 });
}

function unpackHint() {
  return 'unsupported';
}

module.exports = { pack, unpackHint };

